create table cfg_all_area_code_info
(
    id                INT(10) auto_increment comment '自增主键'
        primary key,
    prov_id           VARCHAR(200) null comment '省份编码',
    prov_name         VARCHAR(200) null comment '省份名称',
    city_id           VARCHAR(200) null comment '城市编码',
    city_name         VARCHAR(200) null comment '城市名称',
    county_id         VARCHAR(200) null comment '区县编码',
    county_name       VARCHAR(200) null comment '区县名称',
    alias_prov_name   VARCHAR(200) null comment '省份别名',
    alias_city_name   VARCHAR(200) null comment '城市别名',
    alias_county_name VARCHAR(200) null comment '区县别名',
    city_name_short   VARCHAR(200) null comment '城市简称',
    county_name_short VARCHAR(200) null comment '区县简称'
);

